package com.arcus.alert;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.graphics.Color;import android.view.Gravity;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity{
static final String PREF="arcus_native";LinearLayout root,list;Spinner marketSpinner,modeSpinner;TextView status,livePrice;final ArrayList<String> names=new ArrayList<>();final Handler handler=new Handler(Looper.getMainLooper());
final Runnable refresh=new Runnable(){public void run(){refreshMarkets();handler.postDelayed(this,1000);}};
public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(11,18,32));getWindow().setNavigationBarColor(Color.rgb(11,18,32));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);buildUi();startMonitor();handler.post(refresh);}
int dp(float v){return(int)(v*getResources().getDisplayMetrics().density);}TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(238,244,255));return t;}
void buildUi(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(11,18,32));root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(22),dp(18),dp(28));sc.addView(root);setContentView(sc);root.addView(txt("🔔 Arcus Alert",28));root.addView(txt("Live Arcus market alerts",15));status=txt("Connecting to Arcus markets…",14);status.setPadding(0,dp(14),0,dp(10));root.addView(status);root.addView(txt("Select market",19));marketSpinner=new Spinner(this);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));root.addView(marketSpinner,new LinearLayout.LayoutParams(-1,dp(54)));livePrice=txt("Current price: waiting…",18);livePrice.setPadding(0,dp(8),0,dp(16));root.addView(livePrice);root.addView(txt("Target price",16));EditText target=new EditText(this);target.setSingleLine(true);target.setInputType(8194);target.setHint("Enter target price");target.setTextColor(-1);target.setHintTextColor(Color.GRAY);root.addView(target,new LinearLayout.LayoutParams(-1,dp(52)));modeSpinner=new Spinner(this);modeSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Crosses the level","Touches the level","Approaches within 0.1%"}));root.addView(modeSpinner,new LinearLayout.LayoutParams(-1,dp(50)));Button add=new Button(this);add.setText("Add price alert");root.addView(add);add.setOnClickListener(v->addLevel(target));Button savedBtn=new Button(this);savedBtn.setText("Refresh markets now");root.addView(savedBtn);savedBtn.setOnClickListener(v->refreshMarkets());TextView saved=txt("Saved alerts",20);saved.setPadding(0,dp(18),0,dp(8));root.addView(saved);list=new LinearLayout(this);list.setOrientation(1);root.addView(list);TextView note=txt("Market list and prices refresh every second. Background operation can be affected by battery restrictions.",13);note.setTextColor(Color.LTGRAY);note.setPadding(0,dp(20),0,0);root.addView(note);renderLevels();}
void startMonitor(){try{Intent i=new Intent(this,PriceMonitorService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Monitoring started · 1-second refresh");}catch(Exception e){status.setText("Service error: "+e.getMessage());}}
JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}void save(JSONArray a){getSharedPreferences(PREF,0).edit().putString("levels",a.toString()).apply();}
String selected(){return marketSpinner==null||marketSpinner.getSelectedItem()==null?"":marketSpinner.getSelectedItem().toString();}
JSONObject find(JSONObject d,String s){if(s.isEmpty())return null;Iterator<String> it=d.keys();while(it.hasNext()){JSONObject o=d.optJSONObject(it.next());if(o!=null&&s.equalsIgnoreCase(o.optString("marketDisplayName")))return o;}return null;}
void refreshMarkets(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty()){status.setText("Waiting for Arcus market data…");return;}JSONObject d=new JSONObject(raw);ArrayList<String> fresh=new ArrayList<>();Iterator<String> it=d.keys();while(it.hasNext()){JSONObject o=d.optJSONObject(it.next());if(o!=null){String n=o.optString("marketDisplayName","").trim();if(!n.isEmpty()&&!fresh.contains(n))fresh.add(n);}}Collections.sort(fresh,String.CASE_INSENSITIVE_ORDER);String old=selected();if(!fresh.equals(names)){names.clear();names.addAll(fresh);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));int p=names.indexOf(old);if(p>=0)marketSpinner.setSelection(p);}JSONObject item=find(d,selected());if(item!=null){Object p=item.has("markPrice")&&!item.isNull("markPrice")?item.opt("markPrice"):item.opt("oraclePrice");livePrice.setText("Current price: "+(p==null?"—":p.toString()));}status.setText("Markets: "+names.size()+" · updated just now");}catch(Exception e){status.setText("Market data error: "+e.getMessage());}}
void addLevel(EditText input){String sym=selected();double p;try{p=Double.parseDouble(input.getText().toString().trim());}catch(Exception e){p=0;}if(sym.isEmpty()||p<=0){new AlertDialog.Builder(this).setMessage("Select a market and enter a valid target price.").setPositiveButton("OK",null).show();return;}try{JSONArray a=levels();JSONObject o=new JSONObject();o.put("symbol",sym);o.put("price",p);o.put("mode",modeSpinner.getSelectedItemPosition());o.put("created",System.currentTimeMillis());a.put(o);save(a);input.setText("");renderLevels();}catch(Exception ignored){}}
void renderLevels(){if(list==null)return;list.removeAllViews();JSONArray a=levels();if(a.length()==0){TextView e=txt("No saved alerts yet.",14);e.setTextColor(Color.LTGRAY);list.addView(e);return;}for(int i=0;i<a.length();i++)try{final int idx=i;JSONObject o=a.getJSONObject(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));TextView info=txt(o.getString("symbol")+" · "+o.getDouble("price")+"\n"+new String[]{"Cross","Touch","Near"}[Math.max(0,Math.min(2,o.optInt("mode")))],15);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button del=new Button(this);del.setText("Remove");row.addView(del);del.setOnClickListener(v->{try{JSONArray prev=levels(),next=new JSONArray();for(int j=0;j<prev.length();j++)if(j!=idx)next.put(prev.get(j));save(next);renderLevels();}catch(Exception ignored){}});list.addView(row);}catch(Exception ignored){}}
protected void onDestroy(){handler.removeCallbacks(refresh);super.onDestroy();}
}